import{_ as e,o as r,c as d,a2 as o}from"./chunks/framework.XaTYfhfj.js";const p=JSON.parse('{"title":"Architecture Decision Records (ADR) Log","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),s={name:"system-design/decisions.md"};function i(n,t,a,c,l,u){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="architecture-decision-records-adr-log" tabindex="-1">Architecture Decision Records (ADR) Log <a class="header-anchor" href="#architecture-decision-records-adr-log" aria-label="Permalink to &quot;Architecture Decision Records (ADR) Log&quot;">​</a></h1><p>This decision log documents all architectural and technical design decisions across TruthGuard, recording the chosen solution, evaluated alternatives, deciding factors, and conditions under which the decision should be revisited.</p><hr><h2 id="master-architecture-decisions-table" tabindex="-1">Master Architecture Decisions Table <a class="header-anchor" href="#master-architecture-decisions-table" aria-label="Permalink to &quot;Master Architecture Decisions Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision #</th><th>Architectural Decision</th><th>Chosen Option</th><th>Alternatives Considered</th><th>Deciding Factors</th><th>Trade-Off Accepted</th><th>Revisit When</th></tr></thead><tbody><tr><td><strong>ADR-01</strong></td><td><strong>Frontend Micro-Frontend Topology</strong></td><td>Port-based Federated Hub (<code>FeatureEmbed.tsx</code>)</td><td>Monolithic SPA, Webpack Module Federation, Single-SPA</td><td>Complete failure isolation; independent local development cycles; zero shared dependency lock-in.</td><td>Duplicate browser memory when opening multiple modules simultaneously.</td><td>Modules need to share large in-memory WebGL frame buffers directly.</td></tr><tr><td><strong>ADR-02</strong></td><td><strong>Client-Side Binary Forensics</strong></td><td>Native Web Crypto API (<code>window.crypto.subtle</code>)</td><td>CryptoJS, Node.js server crypto, js-sha256</td><td>Zero bundle weight; compiled C++ execution; evidentiary privacy (media never leaves analyst RAM).</td><td>Requires secure HTTPS context or localhost origin.</td><td>Complex SHA-3 or post-quantum algorithms are mandated by federal law.</td></tr><tr><td><strong>ADR-03</strong></td><td><strong>EXIF Header Parsing Engine</strong></td><td><code>exifr</code> binary parser</td><td><code>exif-js</code>, <code>piexifjs</code>, Sharp (server-side)</td><td>Slices and reads only initial header chunks (~3ms parse time); full support for modern XMP and GPS tags.</td><td>Images stripped of EXIF (e.g., social media downloads) require heuristic fallback.</td><td>Server-side video metadata extraction across petabyte archives is required.</td></tr><tr><td><strong>ADR-04</strong></td><td><strong>State Management for Custody Drive</strong></td><td>Zustand (<code>useMediaVaultStore</code>)</td><td>Redux Toolkit, React Context, Jotai, MobX</td><td>1.1 KB footprint; provider-less architecture; decoupled atomic selector updates during rapid upload progress.</td><td>Lacks enterprise Redux time-travel action replay.</td><td>The application scales to hundreds of complex inter-dependent server cache mutations.</td></tr><tr><td><strong>ADR-05</strong></td><td><strong>Cloud Backend &amp; Database Tier</strong></td><td>Supabase Cloud (PostgreSQL + GoTrue)</td><td>Custom MERN (Express + MongoDB), AWS Amplify, Firebase</td><td>Built-in Row Level Security (RLS); PostgreSQL relational ACID guarantees; serverless Deno Edge Function hosting.</td><td>Relies on third-party cloud infrastructure (mitigated by self-hostable Docker support).</td><td>Air-gapped military deployments with zero internet connectivity are required.</td></tr><tr><td><strong>ADR-06</strong></td><td><strong>AI Inference Strategy</strong></td><td>Pre-Trained Models via Serverless Edge Functions</td><td>Training custom ML models locally, onnxruntime-web in browser</td><td>Zero model training and GPU maintenance cost; instant adaptation to new diffusion architectures; keeps client bundle small.</td><td>Ongoing API token inference cost for high-volume text analysis.</td><td>The company collects 500,000+ proprietary forensic samples and secures private GPU cluster funding.</td></tr><tr><td><strong>ADR-07</strong></td><td><strong>Design System &amp; Styling</strong></td><td>Tailwind CSS with NVIDIA Dark Palette</td><td>Vanilla CSS, CSS Modules, styled-components, Material UI</td><td>Compiles down to &lt;15 KB static CSS; zero JavaScript runtime style injection; exact custom hex tokens.</td><td>Verbose class strings in JSX templates.</td><td>Dynamic user-generated runtime theme creation is required.</td></tr><tr><td><strong>ADR-08</strong></td><td><strong>Dynamic Service Discovery</strong></td><td>Client-Side Port Prober (<code>HEAD / no-cors</code>)</td><td>Hardcoded port URLs, Consul, Eureka service registry</td><td>Works entirely in client browser without running a separate service discovery server daemon.</td><td>Sequential 100ms port probing introduces minor delay on first load.</td><td>Micro-frontends are deployed behind a production reverse proxy with path-based routing.</td></tr><tr><td><strong>ADR-09</strong></td><td><strong>Text Input Length Bound</strong></td><td>Client Slicing to 5,000 Characters</td><td>Unlimited streaming, multi-chunk batching</td><td>Prevents token exhaustion, limits inference latency, and controls cloud billing costs.</td><td>Documents exceeding 5,000 characters require manual multi-part submission.</td><td>Enterprise customers demand multi-hundred-page book and legal brief auditing.</td></tr><tr><td><strong>ADR-10</strong></td><td><strong>Evidence Custody Persistence</strong></td><td>Browser LocalStorage with Exception Handling</td><td>Pure in-memory state, IndexedDB</td><td>Instant zero-setup persistence for prototyping across browser reloads; simple JSON serialization.</td><td>5MB browser storage ceiling limits storage to metadata and small files.</td><td>Production release requires multi-gigabyte video evidence custody and offline caching.</td></tr></tbody></table>',5)])])}const h=e(s,[["render",i]]);export{p as __pageData,h as default};
